assignments.value:
={{
(() => {
  const text = $('Normalize Lead').item.json.normalized_text || '';

  const websiteKeywords = [
    'website',
    'web site',
    'landing page',
    'landing',
    'webshop',
    'ecommerce',
    'e-commerce',
    'online store'
  ];

  const botKeywords = [
    'telegram bot',
    'telegram-bot',
    'chatbot',
    'chat bot',
    'bot'
  ];

  const automationKeywords = [
    'automation',
    'automate',
    'n8n',
    'workflow',
    'crm',
    'integration',
    'webhook',
    'google sheets'
  ];

  if (websiteKeywords.some(keyword => text.includes(keyword))) {
    return 'website';
  }

  if (botKeywords.some(keyword => text.includes(keyword))) {
    return 'bot';
  }

  if (automationKeywords.some(keyword => text.includes(keyword))) {
    return 'automation';
  }

  return 'other';
})()
}}

parameters.text:
={{ 
  $('Classify Lead Type').item.json.lead_type === 'website'
    ? 'Additional question about the website: is there already an example of a website that you like?'
    : $('Classify Lead Type').item.json.lead_type === 'bot'
      ? 'Additional question about the bot: where should the bot save requests—Google Sheets, CRM, or Telegram?'
      : $('Classify Lead Type').item.json.lead_type === 'automation'
        ? 'Additional automation question: which services should be linked first?'
        : 'Additional question: Describe in more detail what exactly needs to be done.'
}}
